package com.javatpoint.servlets;
import java.io.IOException;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import com.javatpoint.dao.BookDao;import com.javatpoint.util.AuthUtil;
@WebServlet("/ReturnBook") public class ReturnBook extends HttpServlet{protected void doPost(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{if(!AuthUtil.requireLibrarian(req,res))return;String callno=req.getParameter("callno"),studentid=req.getParameter("studentid");if(BookDao.returnBook(callno,studentid)>0)res.sendRedirect("ViewIssuedBook");else res.sendError(409,"No active issue was found for this book and student.");}}